import React, { useState } from 'react';
import './FontStyleEditor.css';

interface FontStyles {
  title: {
    fontFamily: string;
    fontSize: string;
    fontWeight: string;
    color: string;
    letterSpacing: string;
  };
  subtitle: {
    fontFamily: string;
    fontSize: string;
    fontWeight: string;
    color: string;
    letterSpacing: string;
  };
  bodyText: {
    fontFamily: string;
    fontSize: string;
    fontWeight: string;
    color: string;
    lineHeight: string;
  };
}

interface FontStyleEditorProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (styles: FontStyles) => void;
  initialStyles?: FontStyles;
}

const FontStyleEditor: React.FC<FontStyleEditorProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  initialStyles 
}) => {
  const [styles, setStyles] = useState<FontStyles>({
    title: {
      fontFamily: initialStyles?.title.fontFamily || 'Georgia, serif',
      fontSize: initialStyles?.title.fontSize || '28px',
      fontWeight: initialStyles?.title.fontWeight || '600',
      color: initialStyles?.title.color || '#cd853f',
      letterSpacing: initialStyles?.title.letterSpacing || '0px'
    },
    subtitle: {
      fontFamily: initialStyles?.subtitle.fontFamily || 'Georgia, serif',
      fontSize: initialStyles?.subtitle.fontSize || '24px',
      fontWeight: initialStyles?.subtitle.fontWeight || '500',
      color: initialStyles?.subtitle.color || '#deb887',
      letterSpacing: initialStyles?.subtitle.letterSpacing || '0px'
    },
    bodyText: {
      fontFamily: initialStyles?.bodyText.fontFamily || 'Arial, sans-serif',
      fontSize: initialStyles?.bodyText.fontSize || '16px',
      fontWeight: initialStyles?.bodyText.fontWeight || '400',
      color: initialStyles?.bodyText.color || '#e0e0e0',
      lineHeight: initialStyles?.bodyText.lineHeight || '1.5'
    }
  });

  const fontFamilies = [
    'Georgia, serif',
    'Times New Roman, serif',
    'Arial, sans-serif',
    'Helvetica, sans-serif',
    'Verdana, sans-serif',
    'Trebuchet MS, sans-serif',
    'Courier New, monospace',
    'Brush Script MT, cursive',
    'Palatino, serif',
    'Garamond, serif'
  ];

  const fontWeights = ['300', '400', '500', '600', '700', '800', '900'];

  const handleStyleChange = (section: keyof FontStyles, property: string, value: string) => {
    setStyles(prev => ({
      ...prev,
      [section]: {
        ...prev[section],
        [property]: value
      }
    }));
  };

  const handleSave = () => {
    onSave(styles);
    onClose();
  };

  const applyPreview = () => {
    // Aplicar estilos temporalmente para preview
    const root = document.documentElement;
    root.style.setProperty('--title-font-family', styles.title.fontFamily);
    root.style.setProperty('--title-font-size', styles.title.fontSize);
    root.style.setProperty('--title-font-weight', styles.title.fontWeight);
    root.style.setProperty('--title-color', styles.title.color);
    root.style.setProperty('--title-letter-spacing', styles.title.letterSpacing);
    
    root.style.setProperty('--subtitle-font-family', styles.subtitle.fontFamily);
    root.style.setProperty('--subtitle-font-size', styles.subtitle.fontSize);
    root.style.setProperty('--subtitle-font-weight', styles.subtitle.fontWeight);
    root.style.setProperty('--subtitle-color', styles.subtitle.color);
    root.style.setProperty('--subtitle-letter-spacing', styles.subtitle.letterSpacing);
    
    root.style.setProperty('--body-font-family', styles.bodyText.fontFamily);
    root.style.setProperty('--body-font-size', styles.bodyText.fontSize);
    root.style.setProperty('--body-font-weight', styles.bodyText.fontWeight);
    root.style.setProperty('--body-color', styles.bodyText.color);
    root.style.setProperty('--body-line-height', styles.bodyText.lineHeight);
  };

  if (!isOpen) return null;

  return (
    <div className="font-style-editor-overlay">
      <div className="font-style-editor-modal">
        <div className="modal-header">
          <h2>🎨 Editor de Estilos de Fuente</h2>
          <button className="close-btn" onClick={onClose}>×</button>
        </div>
        
        <div className="modal-content">
          {/* TÍTULOS */}
          <div className="style-section">
            <h3 className="section-title">📝 Títulos</h3>
            <div className="style-grid">
              <div className="style-field">
                <label>Familia de Fuente</label>
                <select 
                  value={styles.title.fontFamily}
                  onChange={(e) => handleStyleChange('title', 'fontFamily', e.target.value)}
                >
                  {fontFamilies.map(font => (
                    <option key={font} value={font} style={{ fontFamily: font }}>
                      {font.split(',')[0]}
                    </option>
                  ))}
                </select>
              </div>
              
              <div className="style-field">
                <label>Tamaño</label>
                <input
                  type="text"
                  value={styles.title.fontSize}
                  onChange={(e) => handleStyleChange('title', 'fontSize', e.target.value)}
                  placeholder="28px"
                />
              </div>
              
              <div className="style-field">
                <label>Peso</label>
                <select 
                  value={styles.title.fontWeight}
                  onChange={(e) => handleStyleChange('title', 'fontWeight', e.target.value)}
                >
                  {fontWeights.map(weight => (
                    <option key={weight} value={weight}>{weight}</option>
                  ))}
                </select>
              </div>
              
              <div className="style-field">
                <label>Color</label>
                <input
                  type="color"
                  value={styles.title.color}
                  onChange={(e) => handleStyleChange('title', 'color', e.target.value)}
                />
              </div>
              
              <div className="style-field">
                <label>Espaciado de Letras</label>
                <input
                  type="text"
                  value={styles.title.letterSpacing}
                  onChange={(e) => handleStyleChange('title', 'letterSpacing', e.target.value)}
                  placeholder="0px"
                />
              </div>
            </div>
          </div>

          {/* SUBTÍTULOS */}
          <div className="style-section">
            <h3 className="section-title">🔤 Subtítulos</h3>
            <div className="style-grid">
              <div className="style-field">
                <label>Familia de Fuente</label>
                <select 
                  value={styles.subtitle.fontFamily}
                  onChange={(e) => handleStyleChange('subtitle', 'fontFamily', e.target.value)}
                >
                  {fontFamilies.map(font => (
                    <option key={font} value={font} style={{ fontFamily: font }}>
                      {font.split(',')[0]}
                    </option>
                  ))}
                </select>
              </div>
              
              <div className="style-field">
                <label>Tamaño</label>
                <input
                  type="text"
                  value={styles.subtitle.fontSize}
                  onChange={(e) => handleStyleChange('subtitle', 'fontSize', e.target.value)}
                  placeholder="24px"
                />
              </div>
              
              <div className="style-field">
                <label>Peso</label>
                <select 
                  value={styles.subtitle.fontWeight}
                  onChange={(e) => handleStyleChange('subtitle', 'fontWeight', e.target.value)}
                >
                  {fontWeights.map(weight => (
                    <option key={weight} value={weight}>{weight}</option>
                  ))}
                </select>
              </div>
              
              <div className="style-field">
                <label>Color</label>
                <input
                  type="color"
                  value={styles.subtitle.color}
                  onChange={(e) => handleStyleChange('subtitle', 'color', e.target.value)}
                />
              </div>
              
              <div className="style-field">
                <label>Espaciado de Letras</label>
                <input
                  type="text"
                  value={styles.subtitle.letterSpacing}
                  onChange={(e) => handleStyleChange('subtitle', 'letterSpacing', e.target.value)}
                  placeholder="0px"
                />
              </div>
            </div>
          </div>

          {/* TEXTO GENERAL */}
          <div className="style-section">
            <h3 className="section-title">📄 Texto General</h3>
            <div className="style-grid">
              <div className="style-field">
                <label>Familia de Fuente</label>
                <select 
                  value={styles.bodyText.fontFamily}
                  onChange={(e) => handleStyleChange('bodyText', 'fontFamily', e.target.value)}
                >
                  {fontFamilies.map(font => (
                    <option key={font} value={font} style={{ fontFamily: font }}>
                      {font.split(',')[0]}
                    </option>
                  ))}
                </select>
              </div>
              
              <div className="style-field">
                <label>Tamaño</label>
                <input
                  type="text"
                  value={styles.bodyText.fontSize}
                  onChange={(e) => handleStyleChange('bodyText', 'fontSize', e.target.value)}
                  placeholder="16px"
                />
              </div>
              
              <div className="style-field">
                <label>Peso</label>
                <select 
                  value={styles.bodyText.fontWeight}
                  onChange={(e) => handleStyleChange('bodyText', 'fontWeight', e.target.value)}
                >
                  {fontWeights.map(weight => (
                    <option key={weight} value={weight}>{weight}</option>
                  ))}
                </select>
              </div>
              
              <div className="style-field">
                <label>Color</label>
                <input
                  type="color"
                  value={styles.bodyText.color}
                  onChange={(e) => handleStyleChange('bodyText', 'color', e.target.value)}
                />
              </div>
              
              <div className="style-field">
                <label>Altura de Línea</label>
                <input
                  type="text"
                  value={styles.bodyText.lineHeight}
                  onChange={(e) => handleStyleChange('bodyText', 'lineHeight', e.target.value)}
                  placeholder="1.5"
                />
              </div>
            </div>
          </div>

          {/* PREVIEW */}
          <div className="preview-section">
            <h3 className="section-title">👁️ Vista Previa</h3>
            <div className="preview-content">
              <div className="preview-title" style={{
                fontFamily: styles.title.fontFamily,
                fontSize: styles.title.fontSize,
                fontWeight: styles.title.fontWeight,
                color: styles.title.color,
                letterSpacing: styles.title.letterSpacing
              }}>
                Título de Ejemplo
              </div>
              <div className="preview-subtitle" style={{
                fontFamily: styles.subtitle.fontFamily,
                fontSize: styles.subtitle.fontSize,
                fontWeight: styles.subtitle.fontWeight,
                color: styles.subtitle.color,
                letterSpacing: styles.subtitle.letterSpacing
              }}>
                Subtítulo de Ejemplo
              </div>
              <div className="preview-body" style={{
                fontFamily: styles.bodyText.fontFamily,
                fontSize: styles.bodyText.fontSize,
                fontWeight: styles.bodyText.fontWeight,
                color: styles.bodyText.color,
                lineHeight: styles.bodyText.lineHeight
              }}>
                Este es un ejemplo de texto general que muestra cómo se verá el contenido con los estilos seleccionados. Puedes ajustar todos los parámetros y ver los cambios en tiempo real.
              </div>
            </div>
          </div>
        </div>
        
        <div className="modal-actions">
          <button className="preview-btn" onClick={applyPreview}>
            👁️ Aplicar Preview
          </button>
          <button className="cancel-btn" onClick={onClose}>
            Cancelar
          </button>
          <button className="save-btn" onClick={handleSave}>
            💾 Guardar Estilos
          </button>
        </div>
      </div>
    </div>
  );
};

export default FontStyleEditor;
